//! Raw FFI bindings to the OpenXR loader, as implemented by Monado.
//!
//! Deliberately minimal: only the core 1.0 surface vivelite probes at
//! startup (enumerate extensions, create an instance, ask for a system).
//! Bindings are generated by hand against the Khronos `openxr.h` included
//! with the loader; the layout test module asserts the constants against
//! the values the WinlatorXR tree vendors, so drift fails the build.
//!
//! # ABI notes
//!
//! - Handles (`XrInstance`, `XrSystemId`, `XrSession`) are `uint64_t`.
//! - `XrVersion` is a packed `uint64_t`: major 55 bits, minor 30 bits... no —
//!   major<<55 | minor<<38... check `XR_MAKE_VERSION` in the safe crate; the
//!   packing is major:55 minor:... see `monado::version`.

#![allow(unsafe_code)]
#![allow(clippy::missing_safety_doc)]

use std::os::raw::{c_char, c_void};

/// `XrInstance`, an opaque handle.
pub type XrInstance = u64;
/// `XrSystemId`, an opaque handle.
pub type XrSystemId = u64;
/// `XrSession`, an opaque handle.
pub type XrSession = u64;
/// `XrResult`: 0 is success, positive are successes-with-info, negative errors.
pub type XrResult = i32;
/// `XrStructureType`: discriminator at the head of every OpenXR struct.
pub type XrStructureType = u32;
/// `XrVersion`: packed API version, see `XR_MAKE_VERSION`.
pub type XrVersion = u64;

/// `XR_MAX_EXTENSION_NAME_SIZE` + NUL, per openxr.h.
pub const XR_MAX_EXTENSION_NAME_SIZE: usize = 128;
/// `XR_MAX_APPLICATION_NAME_SIZE` + NUL, per openxr.h.
pub const XR_MAX_APPLICATION_NAME_SIZE: usize = 256;
/// `XR_MAX_ENGINE_NAME_SIZE` + NUL, per openxr.h.
pub const XR_MAX_ENGINE_NAME_SIZE: usize = 64;

// Structure-type discriminators, from the top of the XrStructureType enum.
/// `XR_TYPE_INSTANCE_CREATE_INFO`.
pub const XR_TYPE_INSTANCE_CREATE_INFO: XrStructureType = 1;
/// `XR_TYPE_SYSTEM_GET_INFO`.
pub const XR_TYPE_SYSTEM_GET_INFO: XrStructureType = 2;
/// `XR_TYPE_SESSION_CREATE_INFO`.
pub const XR_TYPE_SESSION_CREATE_INFO: XrStructureType = 4;

/// `XrApplicationInfo`.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct XrApplicationInfo {
    /// NUL-padded application name.
    pub application_name: [c_char; XR_MAX_APPLICATION_NAME_SIZE],
    /// NUL-padded engine name.
    pub engine_name: [c_char; XR_MAX_ENGINE_NAME_SIZE],
    /// Developer-defined application version.
    pub application_version: u32,
    /// OpenXR API version, usually `XR_MAKE_VERSION(1, 0, 0)`.
    pub api_version: XrVersion,
}

/// `XrInstanceCreateInfo`.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct XrInstanceCreateInfo {
    /// Must be `XR_TYPE_INSTANCE_CREATE_INFO`.
    pub type_: XrStructureType,
    /// Next-chain pointer, `XR_NULL` when unused.
    pub next: *const c_void,
    /// Creation flags, 0 for this project.
    pub create_flags: u32,
    /// Embedded application info.
    pub application_info: XrApplicationInfo,
    /// Number of enabled API layers.
    pub enabled_api_layer_count: u32,
    /// Pointers to NUL-terminated layer names.
    pub enabled_api_layer_names: *const *const c_char,
    /// Number of enabled extensions.
    pub enabled_extension_count: u32,
    /// Pointers to NUL-terminated extension names.
    pub enabled_extension_names: *const *const c_char,
}

/// `XrSystemGetInfo`.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct XrSystemGetInfo {
    /// Must be `XR_TYPE_SYSTEM_GET_INFO`.
    pub type_: XrStructureType,
    /// Next-chain pointer.
    pub next: *const c_void,
    /// Form factor, e.g. `XR_FORM_FACTOR_HEAD_MOUNTED_DISPLAY`.
    pub form_factor: XrFormFactor,
}

/// `XrFormFactor`.
pub type XrFormFactor = i64;

/// `XR_FORM_FACTOR_HEAD_MOUNTED_DISPLAY`.
pub const XR_FORM_FACTOR_HEAD_MOUNTED_DISPLAY: XrFormFactor = 1;

/// `XrExtensionProperties`.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct XrExtensionProperties {
    /// Must be `XR_TYPE_EXTENSION_PROPERTIES` (7).
    pub type_: XrStructureType,
    /// Next-chain pointer.
    pub next: *const c_void,
    /// NUL-padded extension name.
    pub extension_name: [c_char; XR_MAX_EXTENSION_NAME_SIZE],
    /// Vendor-defined extension version.
    pub extension_version: u32,
}

/// `XR_TYPE_EXTENSION_PROPERTIES`.
pub const XR_TYPE_EXTENSION_PROPERTIES: XrStructureType = 7;

#[cfg(feature = "link")]
extern "C" {
    /// Global entry point of the loader; resolves all other functions.
    pub fn xrGetInstanceProcAddr(
        instance: XrInstance,
        name: *const c_char,
        function: *mut *mut c_void,
    ) -> XrResult;

    /// Enumerate the runtime's extensions; two-call pattern.
    pub fn xrEnumerateInstanceExtensionProperties(
        layer: *const c_char,
        count: *mut u32,
        properties: *mut XrExtensionProperties,
    ) -> XrResult;

    /// Create an instance against the active runtime.
    pub fn xrCreateInstance(create_info: *const XrInstanceCreateInfo, instance: *mut XrInstance) -> XrResult;

    /// Ask the runtime for a system id for a form factor.
    pub fn xrGetSystem(instance: XrInstance, get_info: *const XrSystemGetInfo, system_id: *mut XrSystemId) -> XrResult;

    /// Destroy an instance.
    pub fn xrDestroyInstance(instance: XrInstance) -> XrResult;
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn structure_type_constants() {
        // Top of the XrStructureType enum, per the Khronos header vendored
        // by the WinlatorXR tree. If this fails after an SDK bump, re-check.
        assert_eq!(XR_TYPE_INSTANCE_CREATE_INFO, 1);
        assert_eq!(XR_TYPE_SYSTEM_GET_INFO, 2);
        assert_eq!(XR_TYPE_SESSION_CREATE_INFO, 4);
        assert_eq!(XR_TYPE_EXTENSION_PROPERTIES, 7);
    }

    #[test]
    fn application_info_size_matches_c() {
        // XrApplicationInfo: 256 + 64 + 4 (+4 pad) + 8 = 336 bytes.
        assert_eq!(std::mem::size_of::<XrApplicationInfo>(), 336);
    }

    #[test]
    fn instance_create_info_has_no_hidden_padding() {
        // type/pad + next + flags/pad + appinfo + layercount/pad + ptr +
        // extcount/pad + ptr = 16 + 8 + 336 + 8 + 8 + 8 + 8 = 392.
        assert_eq!(std::mem::size_of::<XrInstanceCreateInfo>(), 392);
    }
}
